-- =====================================================================
-- Session 413 — Testaments of the Twelve Patriarchs FULL-LIBRARY cross-references
-- =====================================================================
-- Per-chapter-range full-library minions (Tanakh + extra-canonical + NT woven
-- per passage). Edition-aware schema; Come-and-See; sacred names restored;
-- son-of-man -> Son of Adam (kaph preserved). Idempotent: ON CONFLICT DO NOTHING.
-- Apply:  python3 api/apply_migration.py data-schema/migrations/session413_testamentsxii_extracanon_cross_references.sql
-- =====================================================================

\echo 'session413 — Testaments of the Twelve Patriarchs cross-references starting...'
BEGIN;

-- ----- fragment: minion_testamentsxii_01.sql (session413 testaments-xii 1) -----
-- Source anchor: pseudepigrapha/testaments-xii ch1. Targets span Tanakh + NT (canon) + extra-canonical.
-- Tag: t1 (view _session413_t1_lookup). Sort band base 87000, step 3. Idempotent ON CONFLICT.

CREATE TEMP VIEW _session413_t1_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-1-defiled-his-fathers-bed
  ('pseudepigrapha', 'testaments-xii', 1, 6, 'canon', 'genesis', 35, 22, 'free', E'Genesis 35:22 — *And it came to pass, when Yashar''el (Israel) dwelt in that land, that Reuben went and lay with Bilhah his father''s concubine: and Yashar''el (Israel) heard it.* The deed Reuben confesses defiling "the bed of my father Jacob" is the very act Moses set down.'),
  ('pseudepigrapha', 'testaments-xii', 1, 6, 'canon', 'genesis', 49, 4, 'free', E'Genesis 49:4 — *Unstable as water, thou shalt not excel; because thou wentest up to thy father''s bed; then defiledst thou it: he went up to my couch.* Jacob''s dying word names the same sin and the lost pre-eminence the testament now laments.')
)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM input i
  JOIN _session413_t1_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _session413_t1_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- ----- threads -----
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-1-defiled-his-fathers-bed',
       E'Reuben''s confession — he defiled his father''s bed',
       E'Reuben opens his deathbed testament by confessing the very sin Genesis records against him: that in the ignorance of youth he defiled the bed of his father Jacob, and was smitten in his loins until Jacob''s prayer spared him. It ain''t new — the testament only owns aloud what Moses already wrote, and the firstborn''s forfeited excellency.',
       sv.verse_id, ev.verse_id, 'extras', 87000
  FROM _session413_t1_lookup sv, _session413_t1_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=1 AND sv.verse_number=6
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=1 AND ev.verse_number=6
ON CONFLICT (slug) DO NOTHING;

-- ----- thread_members -----
-- members: testaments-xii-1-defiled-his-fathers-bed
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, x.id, 1, E'Genesis 35:22 — *And it came to pass, when Yashar''el (Israel) dwelt in that land, that Reuben went and lay with Bilhah his father''s concubine: and Yashar''el (Israel) heard it.* The deed Reuben confesses defiling "the bed of my father Jacob" is the very act Moses set down.'
  FROM cross_reference_threads t, cross_references x, _session413_t1_lookup sv, _session413_t1_lookup tv
 WHERE t.slug='testaments-xii-1-defiled-his-fathers-bed'
   AND sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=1 AND sv.verse_number=6
   AND tv.edition_slug='canon' AND tv.book_slug='genesis' AND tv.chapter_number=35 AND tv.verse_number=22
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual'
ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;

INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, x.id, 2, E'Genesis 49:4 — *Unstable as water, thou shalt not excel; because thou wentest up to thy father''s bed; then defiledst thou it: he went up to my couch.* Jacob''s dying word names the same sin and the lost pre-eminence the testament now laments.'
  FROM cross_reference_threads t, cross_references x, _session413_t1_lookup sv, _session413_t1_lookup tv
 WHERE t.slug='testaments-xii-1-defiled-his-fathers-bed'
