INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-3-spirits-of-error',
       E'The spirits of error — fornication, the belly, anger, pride, lying, injustice',
       E'Reuben catalogues the spirits of error that darken a young man''s mind from the truth — fornication, insatiableness, fighting, pride, lying, injustice. The list is no new psychology: it is the Proverbs'' seven abominations and the works of the flesh, the lust that conceives and brings forth death. It ain''t new — the prophets and the apostles name the same vices and the same cure: love the truth.',
       sv.verse_id, ev.verse_id, 'extras', 87050
  FROM _session413_t3_lookup sv, _session413_t3_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=3 AND sv.verse_number=3
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=3 AND ev.verse_number=9
