WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-5-the-watchers-before-the-flood
  ('pseudepigrapha', 'testaments-xii', 5, 6, 'canon', 'genesis', 6, 2, 'free', E'Genesis 6:2 — *That the sons of Elohim (God) saw the daughters of men that they were fair; and they took them wives of all which they chose.* — the Watchers "who were before the flood" lusting after women is Moses'' record of the sons of Elohim.'),
