INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-6-hearken-to-levi-the-anointed-priest',
       E'Hearken to Levi — the anointed High Priest of whom Yahuah spake',
       E'Reuben charges his sons not to be jealous of the sons of Levi but to draw near in humbleness, for to Levi God gave the sovereignty: he shall know the law, give ordinances for judgment, and sacrifice for all Israel as the anointed High Priest. The hope is the priest-king foretold by Moses and the prophets, a priest upon his throne. It ain''t new — the everlasting priesthood after Melchizedek and the counsel of peace between priest and king were spoken long before.',
       sv.verse_id, ev.verse_id, 'extras', 87125
  FROM _session413_t6_lookup sv, _session413_t6_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=6 AND sv.verse_number=8
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=6 AND ev.verse_number=11
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-6-bow-down-before-his-seed-the-king',
       E'Bow before his seed — an eternal king who dies in wars on our behalf',
       E'Reuben bids his sons bow before Levi''s seed, for on Israel''s behalf it will die in wars visible and invisible and be an eternal king among them. Beneath the legend the testament reaches for the Star out of Jacob and the Sceptre out of Israel, the gathering of the people to Shiloh, the priest-king who lays down his life. It ain''t new — Balaam saw the Star, Jacob saw the Sceptre, and the whole hope is of one anointed from Levi and Judah.',
       sv.verse_id, ev.verse_id, 'extras', 87128
  FROM _session413_t6_lookup sv, _session413_t6_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=6 AND sv.verse_number=11
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=6 AND ev.verse_number=12
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-6-love-each-one-his-neighbour',
       E'Do truth and love, each one to his brother',
       E'Reuben adjures his sons by the God of heaven to do truth each one unto his neighbour and to entertain love each one for his brother. This is the royal law itself, the second great commandment, spoken at a patriarch''s deathbed. It ain''t new — to love thy neighbour as thyself is Moses'' word that all the law and the prophets hang upon.',
       sv.verse_id, ev.verse_id, 'extras', 87131
  FROM _session413_t6_lookup sv, _session413_t6_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=6 AND sv.verse_number=9
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=6 AND ev.verse_number=10
ON CONFLICT (slug) DO NOTHING;

