  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-9-envy-against-joseph
  ('pseudepigrapha', 'testaments-xii', 9, 6, 'canon', 'genesis', 37, 4, 'free', E'Gen 37:4 — *And when his brethren saw that their father loved him more than all his brethren, they hated him, and could not speak peaceably unto him.* — the very father-love and brother-hate Simeon now confesses by name.'),
  ('pseudepigrapha', 'testaments-xii', 9, 6, 'canon', 'genesis', 37, 11, 'free', E'Gen 37:11 — *And his brethren envied him; but his father observed the saying.* — Moses'' one word, "envied," is the seed of Simeon''s whole testament.'),
  ('pseudepigrapha', 'testaments-xii', 9, 7, 'canon', '1-john', 3, 12, 'free', E'1 Jn 3:12 — *Not as Cain, who was of that wicked one, and slew his brother. And wherefore slew he him? Because his own works were evil, and his brother''s righteous.* — the apostle traces brother-murder to envy, just as Simeon traces his plot to "the prince of deceit."'),
  ('pseudepigrapha', 'testaments-xii', 9, 14, 'canon', 'proverbs', 14, 30, 'free', E'Prov 14:30 — *A sound heart is the life of the flesh: but envy the rottenness of the bones.* — Solomon''s diagnosis of the envious heart that Simeon now repents of.'),
  -- thread: testaments-xii-9-judah-sold-him-the-withered-hand
  ('pseudepigrapha', 'testaments-xii', 9, 9, 'canon', 'genesis', 37, 27, 'free', E'Gen 37:27 — *Come, and let us sell him to the Ishmeelites, and let not our hand be upon him; for he is our brother and our flesh. And his brethren were content.* — Judah''s counsel that Simeon recalls, "Judah my brother sold him to the Ishmaelites."'),
  ('pseudepigrapha', 'testaments-xii', 9, 10, 'canon', 'genesis', 37, 22, 'free', E'Gen 37:22 — *And Reuben said unto them, Shed no blood, but cast him into this pit that is in the wilderness, and lay no hand upon him; that he might rid him out of their hands, to deliver him to his father again.* — Reuben''s intent to restore Joseph, which the testament preserves: "he wished to restore him to his father."'),
  ('pseudepigrapha', 'testaments-xii', 9, 13, 'canon', 'proverbs', 27, 4, 'free', E'Prov 27:4 — *Wrath is cruel, and anger is outrageous; but who is able to stand before envy?* — the unstanding-before-envy that left Simeon five months wrathful until his hand withered.')
