-- ----- threads -----
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-9-envy-against-joseph',
       E'Simeon''s confession — the spirit of jealousy against Joseph',
       E'Simeon owns the sin Moses records plainly: the brothers loved Joseph less because their father loved him more, and the jealousy that festered into a plot to destroy him. Genesis names the envy; the testament names the spirit behind it; the Prophets and apostles name what envy does to the one who harbours it. It ain''t new — the rottenness of the bones Solomon warned of is the very thing Simeon confesses on his deathbed.',
       sv.verse_id, ev.verse_id, 'extras', 87200
  FROM _session413_t9_lookup sv, _session413_t9_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=9 AND sv.verse_number=6
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=9 AND ev.verse_number=14
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-9-judah-sold-him-the-withered-hand',
       E'Judah sold him — and the withered hand restrained',
       E'The testament recalls Genesis exactly: it was Judah who counselled selling Joseph to the Ishmaelites, and Reuben who grieved, having meant to restore him to his father. Simeon''s wrath against Judah is checked by the Lord, his hand half-withered until he repents and weeps. It ain''t new — the hand restrained from violence and the heart turned to repentance are the Torah''s own discipline upon a brother who hated.',
       sv.verse_id, ev.verse_id, 'extras', 87203
  FROM _session413_t9_lookup sv, _session413_t9_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=9 AND sv.verse_number=9
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=9 AND ev.verse_number=13
ON CONFLICT (slug) DO NOTHING;

