-- ----- fragment: minion_testamentsxii_10.sql (session413 testaments-xii 10) -----
-- Source anchor: pseudepigrapha/testaments-xii ch10. Targets span Tanakh + NT (canon) + extra-canonical.
-- Tag: t10 (view _session413_t10_lookup). Sort band base 87225, step 3. Idempotent ON CONFLICT.

CREATE TEMP VIEW _session413_t10_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-10-envy-ruleth-the-mind
  ('pseudepigrapha', 'testaments-xii', 10, 2, 'canon', 'proverbs', 14, 30, 'free', E'Prov 14:30 — *A sound heart is the life of the flesh: but envy the rottenness of the bones.* — the wasting Simeon describes, "he that envieth fadeth away."'),
  ('pseudepigrapha', 'testaments-xii', 10, 3, 'canon', 'james', 3, 16, 'free', E'James 3:16 — *For where envying and strife is, there is confusion and every evil work.* — envy''s fruit, the same root Simeon names that "suffereth him to do no good thing."'),
  -- thread: testaments-xii-10-deliverance-by-the-fear-of-the-lord
  ('pseudepigrapha', 'testaments-xii', 10, 4, 'canon', 'proverbs', 14, 27, 'free', E'Prov 14:27 — *The fear of Yahuah (LORD) is a fountain of life, to depart from the snares of death.* — the very deliverance Simeon found: "deliverance from envy cometh by the fear of God."'),
  ('pseudepigrapha', 'testaments-xii', 10, 5, 'canon', 'james', 3, 15, 'free', E'James 3:15 — *This wisdom descendeth not from above, but is earthly, sensual, devilish.* — the "evil spirit" that runneth away when a man flees to the Lord is the devilish wisdom James names.')
)
