INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-10-envy-ruleth-the-mind',
       E'Envy ruleth the mind and wastes the envier',
       E'Simeon describes envy not as a passing mood but as a ruler over the whole mind — it will neither eat nor drink nor do good, but only labours to destroy the one envied, and while the envied flourishes the envier fades away. It ain''t new — Solomon and James say the same: envy rots the bones, and where envying is, there is every evil work.',
       sv.verse_id, ev.verse_id, 'extras', 87225
  FROM _session413_t10_lookup sv, _session413_t10_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=10 AND sv.verse_number=2
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=10 AND ev.verse_number=3
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-10-deliverance-by-the-fear-of-the-lord',
       E'Deliverance from envy by the fear of the Lord',
       E'Simeon learns the cure for envy by fasting and the fear of the Lord: if a man flee to the Lord, the evil spirit runs away and his mind is lightened. It ain''t new — Solomon already called the fear of the Lord a fountain of life, drawing a man away from the snares of death; the patriarch only walks the road Proverbs laid down.',
       sv.verse_id, ev.verse_id, 'extras', 87228
  FROM _session413_t10_lookup sv, _session413_t10_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=10 AND sv.verse_number=4
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=10 AND ev.verse_number=5
ON CONFLICT (slug) DO NOTHING;

