  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-11-joseph-bore-no-malice
  ('pseudepigrapha', 'testaments-xii', 11, 4, 'canon', 'genesis', 50, 20, 'free', E'Gen 50:20 — *But as for you, ye thought evil against me; but Elohim (God) meant it unto good, to bring to pass, as it is this day, to save much people alive.* — Joseph''s own word, the good man who "bore no malice against me."'),
  ('pseudepigrapha', 'testaments-xii', 11, 4, 'canon', 'genesis', 45, 5, 'free', E'Gen 45:5 — *Now therefore be not grieved, nor angry with yourselves, that ye sold me hither: for Elohim (God) did send me before you to preserve life.* — Joseph comforting the very brothers Simeon confesses to, compassionate and pitiful.'),
  ('pseudepigrapha', 'testaments-xii', 11, 6, 'canon', 'genesis', 50, 21, 'free', E'Gen 50:21 — *Now therefore fear ye not: I will nourish you, and your little ones. And he comforted them, and spake kindly unto them.* — Joseph who "gave us riches, and cattle and fruits" and reproached them not.'),
  -- thread: testaments-xii-11-walk-in-singleness-love-the-brethren
  ('pseudepigrapha', 'testaments-xii', 11, 7, 'canon', 'galatians', 5, 14, 'free', E'Gal 5:14 — *For all the law is fulfilled in one word, even in this; Thou shalt love thy neighbour as thyself.* — the brother-love Simeon commands, the law''s one word.'),
  ('pseudepigrapha', 'testaments-xii', 11, 7, 'canon', '1-john', 3, 14, 'free', E'1 Jn 3:14 — *We know that we have passed from death unto life, because we love the brethren. He that loveth not his brother abideth in death.* — "love each one his brother with a good heart," the proof of life John names.'),
  ('pseudepigrapha', 'testaments-xii', 11, 8, 'canon', 'galatians', 5, 21, 'free', E'Gal 5:21 — *Envyings, murders, drunkenness, revellings, and such like... they which do such things shall not inherit the kingdom of Elohim (God).* — the savage works of the flesh, envy that "stirreth up unto deeds of blood."')
)
