-- ----- threads -----
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-11-joseph-bore-no-malice',
       E'Joseph the good man — bearing no malice, repaying evil with good',
       E'Simeon names Joseph a good man with the Spirit of God within him, who bore no malice but loved his brothers as his own soul and never reproached them for what they did. This is Moses'' own portrait of Joseph at the last: "ye thought evil against me; but God meant it unto good." It ain''t new — Joseph forgiving the brothers who sold him is the Messiah-type the Gospel will fill full, the man who repays evil with good.',
       sv.verse_id, ev.verse_id, 'extras', 87250
  FROM _session413_t11_lookup sv, _session413_t11_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=11 AND sv.verse_number=4
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=11 AND ev.verse_number=6
