CREATE TEMP VIEW _session413_t12_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-12-beware-of-fornication
  ('pseudepigrapha', 'testaments-xii', 12, 4, 'enoch', '1-enoch', 8, 2, 'free', E'1 Enoch 8:2 — *And there arose much godlessness, and they committed fornication, and they were led astray, and became corrupt in all their ways.* — the very "writing of Enoch" Simeon cites that his sons "shall be corrupted in fornication."'),
  ('pseudepigrapha', 'testaments-xii', 12, 3, 'canon', 'genesis', 6, 2, 'free', E'Gen 6:2 — *That the sons of Elohim (God) saw the daughters of men that they were fair; and they took them wives of all which they chose.* — the fornication of the Watchers that "bringeth near to Beliar," the root Enoch expounds.'),
  ('pseudepigrapha', 'testaments-xii', 12, 3, 'canon', 'genesis', 6, 11, 'free', E'Gen 6:11 — *The earth also was corrupt before Elohim (God), and the earth was filled with violence.* — fornication "the mother of all evils," filling the earth with corruption as in Noah''s day.'),
  -- thread: testaments-xii-12-levi-and-judah-the-two-tribes
  ('pseudepigrapha', 'testaments-xii', 12, 6, 'canon', 'numbers', 24, 17, 'free', E'Num 24:17 — *there shall come a Star out of Jacob, and a Sceptre shall rise out of Yashar''el (Israel)* — the sovereignty that falls not to Simeon but to the sceptre Balaam foresaw out of Judah.'),
  ('pseudepigrapha', 'testaments-xii', 12, 6, 'canon', 'zechariah', 6, 13, 'free', E'Zech 6:13 — *and he shall be a priest upon his throne: and the counsel of peace shall be between them both.* — the division "in Levi and Judah," priest and king at peace, that Simeon names.')
)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM input i
  JOIN _session413_t12_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _session413_t12_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- ----- threads -----
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-12-beware-of-fornication',
       E'Beware of fornication — the writing of Enoch',
       E'Simeon warns that fornication is the mother of all evils, separating from God and bringing near to Beliar, and he names the source he read it in: the writing of Enoch. That writing tells how the Watchers committed fornication and corrupted all flesh, the corruption Moses records in Genesis. It ain''t new — the patriarch''s warning reaches back to Enoch and to the days of Noah, when fornication first filled the earth with violence.',
       sv.verse_id, ev.verse_id, 'extras', 87275
  FROM _session413_t12_lookup sv, _session413_t12_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=12 AND sv.verse_number=3
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=12 AND ev.verse_number=4
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-12-levi-and-judah-the-two-tribes',
       E'Levi shall prevail — divided in Levi and Judah',
       E'Simeon foresees that none of his own seed shall hold sovereignty; the rule is divided to Levi and Judah, even as Jacob prophesied in his blessings. This is the testament''s quiet bow to the two tribes from whom salvation will arise — the priest of Levi and the sceptre of Judah. It ain''t new — the sceptre belongs to Judah by Jacob''s word and Balaam''s, and Simeon yields his place to the joined hope of the priest-king.',
       sv.verse_id, ev.verse_id, 'extras', 87278
  FROM _session413_t12_lookup sv, _session413_t12_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=12 AND sv.verse_number=5
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=12 AND ev.verse_number=6
ON CONFLICT (slug) DO NOTHING;

