-- ----- fragment: minion_testamentsxii_13.sql (session413 testaments-xii 13) -----
-- Source anchor: pseudepigrapha/testaments-xii ch13. Targets span Tanakh + NT (canon) + extra-canonical.
-- Tag: t13 (view _session413_t13_lookup). Sort band base 87300, step 3. Idempotent ON CONFLICT.

CREATE TEMP VIEW _session413_t13_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-13-the-lord-shall-appear-and-save
  ('pseudepigrapha', 'testaments-xii', 13, 5, 'canon', 'malachi', 3, 1, 'free', E'Mal 3:1 — *and Yahuah (Lord), whom ye seek, shall suddenly come to his temple, even the messenger of the covenant... behold, he shall come, saith Yahuah Tseva''ot (LORD of hosts).* — the Lord appearing on earth to save, the coming Simeon foresees.'),
  ('pseudepigrapha', 'testaments-xii', 13, 5, 'canon', 'zechariah', 14, 9, 'free', E'Zech 14:9 — *And Yahuah (LORD) shall be king over all the earth: in that day shall there be one Yahuah (LORD), and his name one.* — "Yahuah Elohim shall appear on earth" when all the earth rests from war.'),
  ('pseudepigrapha', 'testaments-xii', 13, 5, 'canon', 'genesis', 9, 26, 'free', E'Gen 9:26 — *Blessed be Yahuah Elohim (the LORD God) of Shem; and Canaan shall be his servant.* — "the Mighty One of Israel shall glorify Shem" and Canaan perish, Noah''s blessing fulfilled.'),
  ('pseudepigrapha', 'testaments-xii', 13, 6, 'canon', 'zechariah', 14, 21, 'free', E'Zech 14:21 — *in that day there shall be no more the Canaanite in the house of Yahuah Tseva''ot (LORD of hosts).* — the spirits of deceit trodden under foot and the Canaanite removed in the day of the Lord.'),
  -- thread: testaments-xii-13-the-rest-from-war-and-the-resurrection-joy
  ('pseudepigrapha', 'testaments-xii', 13, 4, 'canon', 'zechariah', 14, 11, 'free', E'Zech 14:11 — *And men shall dwell in it, and there shall be no more utter destruction; but Jerusalem shall be safely inhabited.* — "all the earth rest from trouble, and all the world under heaven from war."'),
  ('pseudepigrapha', 'testaments-xii', 13, 7, 'canon', 'isaiah', 11, 10, 'free', E'Isa 11:10 — *And in that day there shall be a root of Jesse, which shall stand for an ensign of the people; to it shall the Gentiles seek: and his rest shall be glorious.* — the day Simeon shall "arise in joy," the rest of the appearing King.')
)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM input i
  JOIN _session413_t13_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _session413_t13_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- ----- threads -----
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-13-the-lord-shall-appear-and-save',
       E'The Lord shall appear on earth and save the sons of men',
       E'Simeon''s closing prophecy: the Mighty One of Israel shall glorify Shem, the Lord God shall appear on earth and save the sons of men, the spirits of deceit shall be trodden under foot, and he himself shall rise in joy. The prophets foretold the same coming — the Lord suddenly coming to his temple, his feet standing on the mount, the King over all the earth — and the apostles the same crushing of the powers of darkness. It ain''t new — the appearing Simeon awaits is the day the prophets named, when the Lord comes and his saints rule over wicked spirits. (The bracketed clause that God "took a body and ate with men" is a later gloss; the genuine root is the prophesied coming of the Lord to save.)',
       sv.verse_id, ev.verse_id, 'extras', 87300
  FROM _session413_t13_lookup sv, _session413_t13_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=13 AND sv.verse_number=5
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=13 AND ev.verse_number=7
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-13-the-rest-from-war-and-the-resurrection-joy',
       E'My bones shall flourish — and I shall rise in joy',
       E'Simeon promises that if his sons remove their envy his bones shall flourish like a rose in Israel, his branches stretching afar, and at the last he himself shall arise in joy to bless the Most High. The flourishing of dry bones and the rising of the patriarchs in gladness are the prophets'' own hope of resurrection. It ain''t new — Israel''s bones living again and the dead rising in joy is the word of Ezekiel and Isaiah long before Simeon.',
       sv.verse_id, ev.verse_id, 'extras', 87303
  FROM _session413_t13_lookup sv, _session413_t13_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=13 AND sv.verse_number=2
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=13 AND ev.verse_number=7
ON CONFLICT (slug) DO NOTHING;

