-- Tag: t14 (view _session413_t14_lookup). Sort band base 87325, step 3. Idempotent ON CONFLICT.

CREATE TEMP VIEW _session413_t14_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-14-from-levi-and-judah-salvation-arises
  ('pseudepigrapha', 'testaments-xii', 14, 2, 'canon', 'numbers', 24, 17, 'free', E'Num 24:17 — *there shall come a Star out of Jacob, and a Sceptre shall rise out of Yashar''el (Israel)* — the King from Judah whom Simeon bids his sons obey.'),
  ('pseudepigrapha', 'testaments-xii', 14, 2, 'canon', 'zechariah', 6, 13, 'free', E'Zech 6:13 — *and he shall be a priest upon his throne: and the counsel of peace shall be between them both.* — priest and king joined in one, the salvation from Levi and Judah.'),
  ('pseudepigrapha', 'testaments-xii', 14, 2, 'canon', 'psalms', 110, 4, 'free', E'Ps 110:4 — *Yahuah (LORD) hath sworn, and will not repent, Thou art a priest for ever after the order of Melek Tsadiq (Melchizedek).* — the High-priest from Levi who is also the King at the right hand, David''s Lord.'),
  ('pseudepigrapha', 'testaments-xii', 14, 2, 'canon', 'hebrews', 7, 14, 'free', E'Heb 7:14 — *For it is evident that our Lord sprang out of Juda; of which tribe Moses spake nothing concerning priesthood.* — the King out of Judah made a priest, the change Simeon''s priest-king foretells.'),
  ('pseudepigrapha', 'testaments-xii', 14, 2, 'canon', 'hebrews', 7, 25, 'free', E'Heb 7:25 — *Wherefore he is able also to save them to the uttermost that come unto Elohim (God) by him, seeing he ever liveth to make intercession for them.* — "He shall save all the race of Israel," the salvation arising from the two tribes.'),
  -- thread: testaments-xii-14-command-your-children-to-observe
  ('pseudepigrapha', 'testaments-xii', 14, 3, 'canon', 'exodus', 13, 8, 'free', E'Exod 13:8 — *And thou shalt shew thy son in that day, saying, This is done because of that which Yahuah (LORD) did unto me when I came forth out of Egypt.* — the charge to command one''s children that Simeon repeats: "that ye also may command your children."')
)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM input i
  JOIN _session413_t14_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _session413_t14_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- ----- threads -----
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-14-from-levi-and-judah-salvation-arises',
       E'Obey Levi and Judah — from them the salvation of God',
       E'Here is Simeon''s keystone: obey Levi and Judah, for from these two tribes shall arise the salvation of God — the Lord raising up from Levi a High-priest and from Judah a King, to save all the race of Israel. This is the Formed Son, the Father''s Anointed: the priest-king foretold in Balaam''s Star and Sceptre, in Zechariah''s counsel of peace between the two offices, in David''s priest for ever after Melchizedek, and opened in Hebrews. It ain''t new — the joined hope of Levi''s priesthood and Judah''s throne is the whole testimony of Moses and the Prophets, and the Messiah is both.',
       sv.verse_id, ev.verse_id, 'extras', 87325
  FROM _session413_t14_lookup sv, _session413_t14_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=14 AND sv.verse_number=1
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=14 AND ev.verse_number=2
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-14-command-your-children-to-observe',
       E'Command your children to observe these throughout their generations',
       E'Simeon closes by binding his commands on the generations to come: that his sons command their children to observe them always. This is the Torah''s own pattern of teaching the commandments to the children diligently. It ain''t new — the deathbed charge to keep and pass on the words is the very rhythm of Moses.',
       sv.verse_id, ev.verse_id, 'extras', 87328
  FROM _session413_t14_lookup sv, _session413_t14_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=14 AND sv.verse_number=3
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=14 AND ev.verse_number=3
ON CONFLICT (slug) DO NOTHING;

