INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-15-the-bones-carried-up-to-hebron',
       E'His bones taken up — and the bones of Joseph',
       E'Simeon is laid in a wooden coffin, his bones to be carried up to Hebron, while Joseph''s bones the Egyptians guard, for the sorcerers warned that their departure would bring darkness and an exceeding great plague. Moses records the oath Joseph laid on Israel to carry up his bones, the plague of darkness on Egypt, and the day Moses took those bones at the Exodus and Israel buried them in the land. It ain''t new — the carrying up of the patriarchs'' bones is the Torah''s own pledge that God would surely visit his people and bring them home.',
       sv.verse_id, ev.verse_id, 'extras', 87350
  FROM _session413_t15_lookup sv, _session413_t15_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=15 AND sv.verse_number=2
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=15 AND ev.verse_number=4
ON CONFLICT (slug) DO NOTHING;

