SELECT 'testaments-xii-24-seven-men-in-white-anoint-the-priest',
       E'Seven men in white robe Levi in the garments of the priesthood',
       E'In a second vision seven men in white raiment clothe Levi with the robe of the priesthood, the breastplate, the ephod, the turban, and the plate, anoint him with holy oil, wash him with pure water, feed him with bread and wine, crown him, and fill his hands with incense to serve as priest. Every garment and rite is Aaron''s consecration in the Torah. It ain''t new — the holy garments, the anointing oil, the washing and the filling of the hands are Moses'' own ordination of the priest.',
       sv.verse_id, ev.verse_id, 'extras', 87575
  FROM _session413_t24_lookup sv, _session413_t24_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=24 AND sv.verse_number=2
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=24 AND ev.verse_number=10
