INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-25-jacob-pays-tithes-through-levi',
       E'Jacob pays tithes of all to the Lord through Levi',
       E'Coming to Bethel, Jacob sees in a vision that Levi should be priest unto God, rises early, and pays tithes of all to the Lord through him. This is the Bethel vow of Genesis, where Jacob promised the tenth, and the tithe given to the priests of Levi in the Torah. It ain''t new — the tithe through Levi the priest is Jacob''s own Bethel vow brought to its appointed channel.',
       sv.verse_id, ev.verse_id, 'extras', 87600
  FROM _session413_t25_lookup sv, _session413_t25_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=25 AND sv.verse_number=4
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=25 AND ev.verse_number=4
