INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-25-the-law-of-the-priesthood-and-clean-offerings',
       E'The law of the priesthood — clean beasts, washing, and salt',
       E'Isaac instructs Levi continually in the law of the priesthood — to bathe before the holy place, to offer of every clean beast and bird, of first-fruits and wine, and to salt every sacrifice with salt. Each charge is the Torah''s law of offerings, the difference between clean and unclean, and the covenant of salt. It ain''t new — Isaac teaches Levi nothing but Moses'' law of the priesthood, distinguishing clean from unclean and salting every offering.',
       sv.verse_id, ev.verse_id, 'extras', 87603
  FROM _session413_t25_lookup sv, _session413_t25_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=25 AND sv.verse_number=13
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=25 AND ev.verse_number=14
