INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-26-the-veil-rent-scattered-among-the-gentiles',
       E'The veil of the temple rent, Israel scattered among the Gentiles',
       E'Levi foretells that in the end of the ages his sons will deal lawlessly, the veil of the temple shall be rent, and they shall be scattered as captives among the Gentiles for a reproach and a curse. The Gospel records that very veil rent, and Moses foretold the scattering for transgression. It ain''t new — the rent veil and the dispersion among the nations are written in the Torah and fulfilled in the Gospel.',
       sv.verse_id, ev.verse_id, 'extras', 87625
  FROM _session413_t26_lookup sv, _session413_t26_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=26 AND sv.verse_number=3
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=26 AND ev.verse_number=4
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-26-jerusalem-the-house-in-the-book-of-enoch',
       E'The house the Lord shall choose, as in the book of Enoch',
       E'Levi declares that the house which the Lord shall choose shall be called Jerusalem, as is contained in the book of Enoch the righteous. The vision of Enoch indeed saw a new house built greater and loftier than the first, into which the Lord gathered all His own. It ain''t new — Levi names Enoch by his book, and the chosen house of God is the very new house Enoch beheld.',
       sv.verse_id, ev.verse_id, 'extras', 87628
  FROM _session413_t26_lookup sv, _session413_t26_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=26 AND sv.verse_number=5
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=26 AND ev.verse_number=5
ON CONFLICT (slug) DO NOTHING;

