  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-32-the-renewer-of-the-law-called-a-deceiver
  ('pseudepigrapha', 'testaments-xii', 32, 3, 'canon', 'isaiah', 53, 3, 'free', E'Isaiah 53:3 — *He is despised and rejected of men; a man of sorrows, and acquainted with grief.* The renewer of the law whom they ''call a deceiver'' and rush to slay is the despised and rejected one of the prophet.'),
  ('pseudepigrapha', 'testaments-xii', 32, 3, 'canon', 'matthew', 27, 25, 'free', E'Matthew 27:25 — *Then answered all the people, and said, His blood be on us, and on our children.* ''Taking innocent blood through wickedness upon your heads'' is the blood owned by the people in the Gospel.'),
  ('pseudepigrapha', 'testaments-xii', 32, 2, 'canon', 'matthew', 5, 17, 'free', E'Matthew 5:17 — *Think not that I am come to destroy the law, or the prophets: I am not come to destroy, but to fulfil.* That they ''make void the law'' and hate the man who reneweth it sets their lawlessness against the One who came to fulfil it.'),
  -- thread: testaments-xii-32-until-he-shall-again-visit-you
  ('pseudepigrapha', 'testaments-xii', 32, 5, 'canon', 'deuteronomy', 30, 3, 'free', E'Deuteronomy 30:3 — *will return and gather thee from all the nations, whither Yahuah Elohayka (the LORD thy God) hath scattered thee.* ''Until He shall again visit you, and in pity shall receive you'' is the Lord turning the captivity and gathering the scattered.'),
  ('pseudepigrapha', 'testaments-xii', 32, 5, 'canon', 'ezekiel', 37, 21, 'free', E'Ezekiel 37:21 — *I will take the children of Yashar''el (Israel) from among the heathen, whither they be gone, and will gather them on every side.* The visiting mercy after the dispersion is the gathering of the two houses Ezekiel foresees.')
)
