INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-32-the-renewer-of-the-law-called-a-deceiver',
       E'He who reneweth the law called a deceiver — innocent blood taken',
       E'Levi foretells that they shall make void the law, persecute righteous men, and call a deceiver the very man who reneweth the law in the power of the Most High — rushing upon him to slay him, not knowing his dignity, taking innocent blood upon their heads. The Gospel records this innocent blood and the man despised and rejected. It ain''t new — the rejection of the righteous one and the innocent blood are foretold by the prophet and owned at the cross.',
       sv.verse_id, ev.verse_id, 'extras', 87775
  FROM _session413_t32_lookup sv, _session413_t32_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=32 AND sv.verse_number=2
