CREATE TEMP VIEW _session413_t46_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-46-canaanite-race-wicked-blinded-by-wine
  ('pseudepigrapha', 'testaments-xii', 46, 1, 'canon', 'leviticus', 18, 25, 'free', E'Leviticus 18:25 — *And the land is defiled: therefore I do visit the iniquity thereof upon it, and the land itself vomiteth out her inhabitants.* Judah''s verdict that "the race of the Canaanites was wicked" echoes the Law''s judgment on their iniquity.'),
  ('pseudepigrapha', 'testaments-xii', 46, 2, 'canon', 'proverbs', 23, 31, 'free', E'Proverbs 23:31 — *Look not thou upon the wine when it is red, when it giveth his colour in the cup, when it moveth itself aright.* The cup that "deceived" Judah when he saw her pouring out wine is the very snare Proverbs forbids looking upon.'),
  ('pseudepigrapha', 'testaments-xii', 46, 2, 'canon', 'proverbs', 23, 33, 'free', E'Proverbs 23:33 — *Thine eyes shall behold strange women, and thine heart shall utter perverse things.* Judah''s wine-deceived sight of a strange woman is exactly the wine-snare Proverbs describes.')
)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM input i
