SELECT 'testaments-xii-59-a-star-shall-arise-the-sun-of-righteousness',
       E'A star shall arise from Jacob — the Sun of righteousness',
       E'Judah''s crowning prophecy: a star shall arise from Jacob in peace, and a man from his seed like the sun of righteousness, walking with men in meekness and righteousness, in whom no sin is found. It ain''t new — Balaam saw the Star out of Jacob, Malachi the Sun of righteousness arising with healing, and the bright and morning star testifies He is the root and offspring of David.',
       sv.verse_id, ev.verse_id, 'extras', 88450
  FROM _session413_t59_lookup sv, _session413_t59_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=59 AND sv.verse_number=1
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=59 AND ev.verse_number=1
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
