-- ----- fragment: minion_testamentsxii_60.sql (session413 testaments-xii 60) -----
-- Source anchor: pseudepigrapha/testaments-xii ch60. Targets span Tanakh + NT (canon) + extra-canonical.
-- Tag: t60 (view _session413_t60_lookup). Sort band base 88475, step 3. Idempotent ON CONFLICT.

CREATE TEMP VIEW _session413_t60_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-60-abraham-isaac-jacob-shall-arise-unto-life
  ('pseudepigrapha', 'testaments-xii', 60, 1, 'canon', 'daniel', 12, 2, 'free', E'Daniel 12:2 — *And many of them that sleep in the dust of the earth shall awake, some to everlasting life, and some to shame and everlasting contempt.* The patriarchs arising unto life is Daniel''s awakening of them that sleep in the dust.'),
  ('pseudepigrapha', 'testaments-xii', 60, 1, 'canon', 'isaiah', 26, 19, 'free', E'Isaiah 26:19 — *Thy dead men shall live, together with my dead body shall they arise. Awake and sing, ye that dwell in dust: for thy dew is as the dew of herbs, and the earth shall cast out the dead.* The rising of the fathers unto life is Isaiah''s dead men living and rising.'),
  ('pseudepigrapha', 'testaments-xii', 60, 1, 'canon', 'matthew', 22, 32, 'free', E'Matthew 22:32 — *I am the Elohim (God) of Abraham, and the Elohim (God) of Isaac, and the Elohim (God) of Jacob? Elohim (God) is not the Elohim (God) of the dead, but of the living.* Judah''s very three fathers arising are the Master''s proof of the resurrection.'),
  -- thread: testaments-xii-60-beliar-cast-into-the-fire-for-ever
  ('pseudepigrapha', 'testaments-xii', 60, 3, 'canon', 'revelation', 20, 3, 'free', E'Revelation 20:3 — *And cast him into the bottomless pit, and shut him up, and set a seal upon him, that he should deceive the nations no more, till the thousand years should be fulfilled.* Beliar cast into the fire so there is no more spirit of deceit is the deceiver shut up that he deceive the nations no more.'),
  ('pseudepigrapha', 'testaments-xii', 60, 3, 'canon', 'ezekiel', 37, 12, 'free', E'Ezekiel 37:12 — *...Behold, O my people, I will open your graves, and cause you to come up out of your graves, and bring you into the land of Yashar''el (Israel).* Israel made one people of Yahuah with one tongue is the whole house brought up out of the graves into the land.'),
  -- thread: testaments-xii-60-they-who-died-in-grief-shall-arise-in-joy
  ('pseudepigrapha', 'testaments-xii', 60, 4, 'canon', '1-thessalonians', 4, 14, 'free', E'1 Thessalonians 4:14 — *For if we believe that Yahusha (Jesus) died and rose again, even so them also which sleep in Yahusha (Jesus) will Elohim (God) bring with him.* They who died in grief arising in joy is the apostle''s hope that Elohim will bring the sleeping with Him.'),
  ('pseudepigrapha', 'testaments-xii', 60, 4, 'canon', '1-corinthians', 15, 22, 'free', E'1 Corinthians 15:22 — *For as in Adam all die, even so in Messiah (Christ) shall all be made alive.* The dead in grief made to awake to life is the all-made-alive in Messiah.'),
  ('pseudepigrapha', 'testaments-xii', 60, 4, 'canon', 'revelation', 20, 6, 'free', E'Revelation 20:6 — *Blessed and holy is he that hath part in the first resurrection: on such the second death hath no power, but they shall be priests of Elohim (God) and of Messiah (Christ), and shall reign with him a thousand years.* They put to death for Yahuah''s sake awaking to life are blessed in the first resurrection.')
)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM input i
  JOIN _session413_t60_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _session413_t60_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- ----- threads -----
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-60-abraham-isaac-jacob-shall-arise-unto-life',
       E'Abraham, Isaac, and Jacob shall arise unto life',
       E'Judah''s last vision: Abraham and Isaac and Jacob shall arise unto life, and the patriarchs shall be chiefs of the tribes. It ain''t new — Daniel foretold that they who sleep in the dust shall awake, Isaiah that the dead men shall live and rise, and the Master proved the resurrection from the God of Abraham, Isaac, and Jacob, who is not the God of the dead but of the living.',
       sv.verse_id, ev.verse_id, 'extras', 88475
  FROM _session413_t60_lookup sv, _session413_t60_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=60 AND sv.verse_number=1
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=60 AND ev.verse_number=1
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-60-beliar-cast-into-the-fire-for-ever',
       E'Beliar cast into the fire for ever — one people of Yahuah',
       E'Judah foresees Israel made the people of Yahuah with one tongue, with no spirit of deceit of Beliar, for he shall be cast into the fire for ever. It ain''t new — Ezekiel saw the dry bones come up out of their graves into the land, and Revelation the deceiver bound and cast away that he should deceive the nations no more.',
       sv.verse_id, ev.verse_id, 'extras', 88478
  FROM _session413_t60_lookup sv, _session413_t60_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=60 AND sv.verse_number=3
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=60 AND ev.verse_number=3
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-60-they-who-died-in-grief-shall-arise-in-joy',
       E'They who died in grief shall arise in joy',
       E'Judah foretells that they who died in grief shall arise in joy, and they who were put to death for Yahuah''s sake shall awake to life. It ain''t new — the apostle promised that Elohim will bring with Him them that sleep, and that the dead in Messiah shall rise; and Revelation pronounces blessed they who have part in the first resurrection.',
       sv.verse_id, ev.verse_id, 'extras', 88481
  FROM _session413_t60_lookup sv, _session413_t60_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=60 AND sv.verse_number=4
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=60 AND ev.verse_number=4
ON CONFLICT (slug) DO NOTHING;

