CREATE TEMP VIEW _session413_t64_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-64-singleness-of-eye
  ('pseudepigrapha', 'testaments-xii', 64, 4, 'canon', 'matthew', 6, 22, 'free', E'Matthew 6:22 — *The light of the body is the eye: if therefore thine eye be single, thy whole body shall be full of light.* Issachar''s "singleness of eye" is the very single eye the Master makes the lamp of the whole man.'),
  ('pseudepigrapha', 'testaments-xii', 64, 3, 'canon', 'proverbs', 22, 9, 'free', E'Proverbs 22:9 — *He that hath a bountiful eye shall be blessed; for he giveth of his bread to the poor.* The single, unenvious eye that grudges no neighbour is Proverbs'' bountiful eye, blessed for its open hand.'),
  ('pseudepigrapha', 'testaments-xii', 64, 1, 'canon', 'matthew', 5, 8, 'free', E'Matthew 5:8 — *Blessed are the pure in heart: for they shall see Elohim (God).* The uprightness and singleness of heart Issachar walked in is the purity of heart the Beatitude crowns.'),
  -- thread: testaments-xii-64-firstfruits-and-the-poor
  ('pseudepigrapha', 'testaments-xii', 64, 6, 'canon', 'deuteronomy', 26, 2, 'free', E'Deuteronomy 26:2 — *That thou shalt take of the first of all the fruit of the earth, which thou shalt bring of thy land that Yahuah Elohayka (the LORD thy God) giveth thee, and shalt put it in a basket, and shalt go unto the place which Yahuah Elohayka (the LORD thy God) shall choose to place his name there.* Issachar''s offering of all his first-fruits through the priest keeps the Torah''s command exactly.'),
  ('pseudepigrapha', 'testaments-xii', 64, 6, 'canon', 'proverbs', 3, 9, 'free', E'Proverbs 3:9 — *Honour Yahuah (LORD) with thy substance, and with the firstfruits of all thine increase.* The husbandman who first honours Yahuah with his increase walks Wisdom''s path.'),
  ('pseudepigrapha', 'testaments-xii', 64, 8, 'canon', '2-corinthians', 9, 7, 'free', E'2 Corinthians 9:7 — *Every man according as he purposeth in his heart, so let him give; not grudgingly, or of necessity: for Elohim (God) loveth a cheerful giver.* Bestowing on the poor "in the singleness of my heart" is the cheerful, ungrudging giving the apostle commends.')
)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM input i
  JOIN _session413_t64_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _session413_t64_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

