  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-66-love-the-lord-and-thy-neighbour
  ('pseudepigrapha', 'testaments-xii', 66, 2, 'canon', 'deuteronomy', 6, 5, 'free', E'Deuteronomy 6:5 — *And thou shalt love Yahuah Elohayka (the LORD thy God) with all thine heart, and with all thy soul, and with all thy might.* "Love Yahuah" is the first great word of the Shema, set first by Issachar as by Moses.'),
  ('pseudepigrapha', 'testaments-xii', 66, 2, 'canon', 'leviticus', 19, 18, 'free', E'Leviticus 19:18 — *Thou shalt not avenge, nor bear any grudge against the children of thy people, but thou shalt love thy neighbour as thyself: I am Yahuah (LORD).* "Love your neighbour" and "have compassion on the poor and weak" is Torah''s royal command set beside the love of God.'),
  ('pseudepigrapha', 'testaments-xii', 66, 1, 'canon', 'matthew', 22, 40, 'free', E'Matthew 22:40 — *On these two commandments hang all the law and the prophets.* Issachar''s "keep the law of God" reduced to love of God and neighbour is the very hinge the Master names.'),
  -- thread: testaments-xii-66-first-fruits-blessing
  ('pseudepigrapha', 'testaments-xii', 66, 3, 'canon', 'exodus', 23, 19, 'free', E'Exodus 23:19 — *The first of the firstfruits of thy land thou shalt bring into the house of Yahuah Elohayka (the LORD thy God).* Issachar''s "offering gifts to Yahuah with thanksgiving" from the first-fruits keeps the Torah''s command.'),
  ('pseudepigrapha', 'testaments-xii', 66, 4, 'canon', 'proverbs', 3, 10, 'free', E'Proverbs 3:10 — *So shall thy barns be filled with plenty, and thy presses shall burst out with new wine.* The promise that with first-fruits Yahuah will bless the husbandman echoes Wisdom''s reward for honouring Him with the increase.'),
