-- ----- fragment: minion_testamentsxii_78.sql (session413 testaments-xii 78) -----
-- Source anchor: pseudepigrapha/testaments-xii ch78. Targets span Tanakh + NT (canon) + extra-canonical.
-- Tag: t78 (view _session413_t78_lookup). Sort band base 88925, step 3. Idempotent ON CONFLICT.

CREATE TEMP VIEW _session413_t78_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-78-i-shall-rise-again
  ('pseudepigrapha', 'testaments-xii', 78, 2, 'canon', 'daniel', 12, 2, 'free', E'Daniel 12:2 — *And many of them that sleep in the dust of the earth shall awake, some to everlasting life, and some to shame and everlasting contempt.* Zebulun''s confidence that he shall rise again in the midst of his sons rests on the awaking from the dust Daniel foretold.'),
  ('pseudepigrapha', 'testaments-xii', 78, 2, 'canon', 'isaiah', 26, 19, 'free', E'Isaiah 26:19 — *Thy dead men shall live, together with my dead body shall they arise. Awake and sing, ye that dwell in dust: for thy dew is as the dew of herbs, and the earth shall cast out the dead.* That he shall rise and rejoice in the midst of his tribe is the awaking and singing of the dust Isaiah promised.'),
  ('pseudepigrapha', 'testaments-xii', 78, 7, 'canon', 'genesis', 49, 29, 'free', E'Genesis 49:29 — *I am to be gathered unto my people: bury me with my fathers in the cave that is in the field of Ephron the Hittite.* Zebulun carried up and buried in Hebron with his fathers keeps the same burial among the patriarchs Jacob charged.')
)
