INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-79-truth-and-lying-and-anger',
       E'Truth pleases God; lying and anger teach all wickedness',
       E'Dan''s opening confession sets the whole testament''s frame: truth with just dealing pleases God, while lying and anger are the twin evils that teach a man every wickedness. The apostles say nothing different — put away lying and speak truth, and be angry without sinning. It ain''t new: the choice between the spirit of truth and the spirit of lying runs straight back through Moses and the Prophets.',
       sv.verse_id, ev.verse_id, 'extras', 88950
  FROM _session413_t79_lookup sv, _session413_t79_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=79 AND sv.verse_number=3
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=79 AND ev.verse_number=3
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-79-spirit-of-beliar-and-the-sword',
       E'The spirit of Beliar stirs up the sword against Joseph',
       E'Dan confesses that a spirit of Beliar put a sword in his heart against Joseph the true and good man — but the God of his fathers would not suffer it, sparing a second tribe from destruction in Israel. The Gospel names this prompter: the devil, a murderer and the father of lies from the beginning. It ain''t new — envy that reaches for a brother''s blood is the old serpent''s work, restrained by the God who keeps His own.',
       sv.verse_id, ev.verse_id, 'extras', 88953
  FROM _session413_t79_lookup sv, _session413_t79_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=79 AND sv.verse_number=7
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=79 AND ev.verse_number=9
ON CONFLICT (slug) DO NOTHING;

