-- ----- fragment: minion_testamentsxii_84.sql (session413 testaments-xii 84) -----
-- Source anchor: pseudepigrapha/testaments-xii ch84. Targets span Tanakh + NT (canon) + extra-canonical.
-- Tag: t84 (view _session413_t84_lookup). Sort band base 89075, step 3. Idempotent ON CONFLICT.

CREATE TEMP VIEW _session413_t84_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-84-the-mediator-between-god-and-man
  ('pseudepigrapha', 'testaments-xii', 84, 2, 'canon', '1-timothy', 2, 5, 'free', E'1 Tim 2:5 — *For there is one God, and one mediator between God and men, the man Christ Jesus.* The single mediator Dan tells his sons to draw near to — the appointed Anointed, not a co-equal, but the man who stands between God and Israel.'),
  ('pseudepigrapha', 'testaments-xii', 84, 2, 'canon', 'hebrews', 7, 25, 'free', E'Heb 7:25 — *seeing he ever liveth to make intercession for them.* The intercession of the priest-king, exactly the office Dan ascribes to the one who pleads Israel''s peace.'),
  -- thread: testaments-xii-84-repent-and-the-enemys-kingdom-ends
  ('pseudepigrapha', 'testaments-xii', 84, 4, 'canon', 'deuteronomy', 30, 2, 'free', E'Deut 30:2 — *And shalt return unto the LORD thy God, and shalt obey his voice... with all thine heart.* The day of Israel''s repentance on which Dan says the enemy''s kingdom ends.'),
  ('pseudepigrapha', 'testaments-xii', 84, 6, 'canon', 'ezekiel', 37, 23, 'free', E'Ezek 37:23 — *but I will save them out of all their dwellingplaces, wherein they have sinned, and will cleanse them: so shall they be my people.* The transforming into a nation that does His will, which Dan promises the repentant.'),
  ('pseudepigrapha', 'testaments-xii', 84, 7, 'canon', 'deuteronomy', 30, 4, 'free', E'Deut 30:4 — *from thence will the LORD thy God gather thee, and from thence will he fetch thee.* The Lord''s name in every place of Israel and among the Gentiles — the gathering of the scattered Dan foresees.')
)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM input i
  JOIN _session413_t84_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _session413_t84_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- ----- threads -----
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-84-the-mediator-between-god-and-man',
       E'Draw near to the mediator between God and man',
       E'Dan bids his sons draw near to God and to the one who intercedes for them — a mediator between God and man who stands up for Israel''s peace against the kingdom of the enemy. Paul names one mediator between God and men, the man Messiah Yahusha, who ever lives to make intercession. It ain''t new: the appointed Anointed who stands between God and His people, pleading their peace, is the priest-king of Levi and Judah''s hope.',
       sv.verse_id, ev.verse_id, 'extras', 89075
  FROM _session413_t84_lookup sv, _session413_t84_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=84 AND sv.verse_number=2
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=84 AND ev.verse_number=2
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-84-repent-and-the-enemys-kingdom-ends',
       E'When Israel repents, the kingdom of the enemy is ended',
       E'Dan foretells that on the day Israel repents, the kingdom of the enemy is brought to an end, the Lord will not depart but transform them into a nation that does His will, and His name shall be in every place of Israel and among the Gentiles. This is Moses'' promise of return and gathering, and Ezekiel''s of a cleansed people the Lord saves and dwells among. It ain''t new — repentance ends the enemy''s reign and the Lord makes His scattered people His own again.',
       sv.verse_id, ev.verse_id, 'extras', 89078
  FROM _session413_t84_lookup sv, _session413_t84_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=84 AND sv.verse_number=4
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=84 AND ev.verse_number=7
ON CONFLICT (slug) DO NOTHING;

