CREATE TEMP VIEW _session413_t86_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-86-born-of-bilhah-upon-rachels-knees
  ('pseudepigrapha', 'testaments-xii', 86, 6, 'canon', 'genesis', 30, 8, 'free', E'Genesis 30:8 — *And Rachel said, With great wrestlings have I wrestled with my sister, and I have prevailed: and she called his name Naphtali.* — Naphtali''s word that Bilhah "conceived and bare me upon Rachel''s knees, therefore she called my name Naphtali" is the very naming Moses set down.'),
  ('pseudepigrapha', 'testaments-xii', 86, 6, 'canon', 'genesis', 30, 7, 'free', E'Genesis 30:7 — *And Bilhah Rachel’s maid conceived again, and bare Jacob a second son.* — "I was born from Bilhah... and she conceived and bare me" is the birth of that second son of Bilhah.'),
  ('pseudepigrapha', 'testaments-xii', 86, 8, 'canon', 'genesis', 35, 24, 'free', E'Genesis 35:24 — *The sons of Rachel; Joseph, and Benjamin:* — Rachel''s prayer for "a brother of thine from mine own womb," whence "Joseph was like unto me in all things," reaches for the sons Rachel herself bore.')
)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM input i
  JOIN _session413_t86_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _session413_t86_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
