INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-87-the-potter-and-the-vessel',
       E'As the potter knoweth the vessel — Yahuah forms body and spirit',
       E'Naphtali likens the Maker to a potter who knows how much each vessel will hold and brings clay accordingly: so Yahuah forms the body after the likeness of the spirit, and knows every inclination and thought, for He created every man after His own image. The figure is not Naphtali''s invention. It ain''t new — Isaiah and Jeremiah called Yahuah the potter and Israel the clay, and the psalmist confessed he was fearfully and wonderfully made, his frame searched and known.',
       sv.verse_id, ev.verse_id, 'extras', 89150
  FROM _session413_t87_lookup sv, _session413_t87_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=87 AND sv.verse_number=2
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=87 AND ev.verse_number=5
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-87-all-things-good-in-their-order',
       E'God made all things good in their order — do nothing disorderly',
       E'Naphtali marvels at the ordered frame of the body — the senses set in their places, each member to its work — and concludes that as God made all things good in their order, so His children should do all their works in order and in the fear of God, doing nothing disorderly or out of its due season. The order is borrowed from creation itself. It ain''t new — God divided light from darkness and saw that every thing He had made was very good.',
       sv.verse_id, ev.verse_id, 'extras', 89153
  FROM _session413_t87_lookup sv, _session413_t87_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=87 AND sv.verse_number=7
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=87 AND ev.verse_number=10
ON CONFLICT (slug) DO NOTHING;

