INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM input i
  JOIN _session413_t88_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _session413_t88_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- ----- threads -----
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-88-change-not-the-law-as-the-luminaries-change-not-their-order',
       E'Sun, moon and stars change not their order — change not the law of God',
       E'Naphtali points to the firmament: sun and moon and stars change not their order, and bids his children likewise not change the law of God in the disorderliness of their doings — recognising in heaven, earth and sea the LORD who made all things. The witness of the ordered heavens is no new argument. It ain''t new — Moses set the lights in the firmament for signs and seasons, the psalmist heard the heavens declare the glory of God, and Paul read His eternal power in the things that are made.',
       sv.verse_id, ev.verse_id, 'extras', 89175
  FROM _session413_t88_lookup sv, _session413_t88_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=88 AND sv.verse_number=2
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=88 AND ev.verse_number=4
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-88-sodom-and-the-watchers-changed-the-order-of-nature',
       E'Sodom and the Watchers changed the order of nature',
       E'Naphtali warns his children not to become as Sodom, which changed the order of nature, nor as the Watchers who likewise changed the order of their nature, whom the LORD cursed at the flood. The Gentiles forsook their Maker and served stocks and stones; God''s children must not. It ain''t new — Genesis tells of Sodom and of the sons of God who took wives of the daughters of men, 1 Enoch tells how the Watchers corrupted the earth, and the apostles set both forth as a warning of the vengeance reserved for them.',
       sv.verse_id, ev.verse_id, 'extras', 89178
  FROM _session413_t88_lookup sv, _session413_t88_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=88 AND sv.verse_number=3
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=88 AND ev.verse_number=5
ON CONFLICT (slug) DO NOTHING;

