-- ----- fragment: minion_testamentsxii_90.sql (session413 testaments-xii 90) -----
-- Source anchor: pseudepigrapha/testaments-xii ch90. Targets span Tanakh + NT (canon) + extra-canonical.
-- Tag: t90 (view _session413_t90_lookup). Sort band base 89225, step 3. Idempotent ON CONFLICT.

CREATE TEMP VIEW _session413_t90_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-90-levi-the-sun-judah-the-moon
  ('pseudepigrapha', 'testaments-xii', 90, 1, 'canon', 'genesis', 37, 9, 'free', E'Genesis 37:9 — *Behold, I have dreamed a dream more; and, behold, the sun and the moon and the eleven stars made obeisance to me.* — Naphtali''s vision "that the sun and the moon were standing still" takes up the very luminaries of Joseph''s dream among the brethren.'),
  ('pseudepigrapha', 'testaments-xii', 90, 3, 'canon', 'numbers', 24, 17, 'free', E'Numbers 24:17 — *there shall come a Star out of Jacob, and a Sceptre shall rise out of Yashar''el (Israel), and shall smite the corners of Moab, and destroy all the children of Sheth.* — that Levi seizes the sun and Judah the moon, both lifted up, is the priest-king hope summed in the Star of Jacob and the Sceptre of Israel.'),
  ('pseudepigrapha', 'testaments-xii', 90, 3, 'canon', 'zechariah', 6, 13, 'free', E'Zechariah 6:13 — *and he shall be a priest upon his throne: and the counsel of peace shall be between them both.* — Levi as the sun and Judah as the moon, raised together, is the counsel of peace between priest and king.'),
  -- thread: testaments-xii-90-the-twelve-tribes-led-into-captivity
  ('pseudepigrapha', 'testaments-xii', 90, 8, 'canon', 'deuteronomy', 30, 1, 'free', E'Deuteronomy 30:1 — *...thou shalt call them to mind among all the nations, whither Yahuah Elohayka (the LORD thy God) hath driven thee,* — that the nations "shall possess in captivity the twelve tribes of Yashar''el" is the driving among the nations Moses set before them.'),
  ('pseudepigrapha', 'testaments-xii', 90, 8, 'canon', 'ezekiel', 37, 22, 'free', E'Ezekiel 37:22 — *And I will make them one nation in the land upon the mountains of Yashar''el (Israel)... and they shall be no more two nations, neither shall they be divided into two kingdoms any more at all:* — the captivity of all twelve tribes looks to the day Ezekiel foretells, when the divided house is made one nation again.')
)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM input i
  JOIN _session413_t90_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _session413_t90_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

