INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM input i
  JOIN _session413_t93_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _session413_t93_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- ----- threads -----
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-93-through-levi-and-judah-salvation-arises',
       E'Be united to Levi and to Judah — through them salvation arises',
       E'Naphtali charges his children to be united to Levi and to Judah, for through them shall salvation arise unto Israel and in them shall Jacob be blessed. This is the spine of all twelve Testaments: the priest of Levi and the king of Judah joined in one anointed hope. It ain''t new — Balaam saw the Star out of Jacob, Zechariah the priest upon his throne with the counsel of peace between the two, and the blessing of Jacob rested the sceptre upon Judah.',
       sv.verse_id, ev.verse_id, 'extras', 89300
  FROM _session413_t93_lookup sv, _session413_t93_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=93 AND sv.verse_number=2
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=93 AND ev.verse_number=2
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-93-god-shall-appear-dwelling-among-men',
       E'God shall appear, dwelling among men, to save Israel and gather the Gentiles',
       E'Through the tribes of Levi and Judah, Naphtali prophesies, God shall appear, dwelling among men on earth, to save the race of Israel and to gather together the righteous from amongst the Gentiles. The Father made Himself manifest in the Anointed of the joined tribes — come to dwell, to save His people, and to draw the nations in. It ain''t new — Zechariah heard the LORD say He would dwell in the midst of Zion and many nations be joined to Him; the prophet set up an ensign for the nations and gathered the outcasts; and the Word was made flesh and dwelt among us, Immanuel, God with us.',
       sv.verse_id, ev.verse_id, 'extras', 89303
  FROM _session413_t93_lookup sv, _session413_t93_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=93 AND sv.verse_number=3
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=93 AND ev.verse_number=3
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-93-the-commandments-twofold-fulfilled-in-prudence',
       E'The commandments of the law are twofold — kept in due order and prudence',
       E'Naphtali closes by teaching that the commandments of the law are twofold and must be fulfilled through prudence and in due order — a season to embrace and a season to abstain for prayer — that the LORD may love them. The law is honoured, not loosed; it is to be understood and kept wisely. It ain''t new — there is a season to every purpose under heaven, and the wise lay hold of the order of God''s commandments.',
       sv.verse_id, ev.verse_id, 'extras', 89306
  FROM _session413_t93_lookup sv, _session413_t93_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=93 AND sv.verse_number=7
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=93 AND ev.verse_number=10
ON CONFLICT (slug) DO NOTHING;

