-- ----- fragment: minion_testamentsxii_95.sql (session413 testaments-xii 95) -----
-- Source anchor: pseudepigrapha/testaments-xii ch95. Targets span Tanakh + NT (canon) + extra-canonical.
-- Tag: t95 (view _session413_t95_lookup). Sort band base 89350, step 3. Idempotent ON CONFLICT.

CREATE TEMP VIEW _session413_t95_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-95-joseph-the-evil-report
  ('pseudepigrapha', 'testaments-xii', 95, 6, 'canon', 'genesis', 37, 2, 'free', E'Genesis 37:2 — *These are the generations of Jacob. Joseph, being seventeen years old, was feeding the flock with his brethren; and the lad was with the sons of Bilhah, and with the sons of Zilpah, his father’s wives: and Joseph brought unto his father their evil report.* The very scene Gad describes — Joseph with the sons of Bilhah, carrying their report to their father.'),
  ('pseudepigrapha', 'testaments-xii', 95, 9, 'canon', 'genesis', 37, 4, 'free', E'Genesis 37:4 — *And when his brethren saw that their father loved him more than all his brethren, they hated him, and could not speak peaceably unto him.* The grudge Gad confesses is the brethren''s hatred Moses names.'),
  -- thread: testaments-xii-95-spirit-of-hatred
  ('pseudepigrapha', 'testaments-xii', 95, 9, 'canon', '1-john', 2, 9, 'free', E'1 John 2:9 — *He that saith he is in the light, and hateth his brother, is in darkness even until now.* Gad''s spirit of hatred toward his brother is exactly the darkness John exposes.'),
  ('pseudepigrapha', 'testaments-xii', 95, 9, 'canon', '1-john', 2, 11, 'free', E'1 John 2:11 — *But he that hateth his brother is in darkness, and walketh in darkness, and knoweth not whither he goeth, because that darkness hath blinded his eyes.* That Gad would neither hear nor see Joseph is the blinded eyes John describes.')
)
