INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-95-joseph-the-evil-report',
       E'Gad and the brothers — Joseph''s report to their father',
       E'Gad opens his deathbed testament by retracing the quarrel Genesis records: Joseph, feeding the flock with his brethren and the sons of Bilhah, carries to their father the report that they were slaying the best of the flock — and Gad is wroth with him until the day he is sold. It ain''t new — the testament only confesses from the inside the very evil report and grudge Moses set down.',
       sv.verse_id, ev.verse_id, 'extras', 89350
  FROM _session413_t95_lookup sv, _session413_t95_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=95 AND sv.verse_number=6
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=95 AND ev.verse_number=9
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-95-spirit-of-hatred',
       E'The spirit of hatred — would not hear or see his brother',
       E'Gad confesses that the spirit of hatred was in him, so that he wished not to hear of Joseph with the ears nor see him with the eyes. The apostle John names the same darkness: he that hateth his brother walketh in darkness and his eyes are blinded. It ain''t new — the testament''s confession is the very blindness John warns the children against.',
       sv.verse_id, ev.verse_id, 'extras', 89353
  FROM _session413_t95_lookup sv, _session413_t95_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=95 AND sv.verse_number=9
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=95 AND ev.verse_number=9
