INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-100-love-one-another-from-the-heart',
       E'Love one another from the heart — put away hatred',
       E'The heart of Gad''s testament: love one another from the heart, and put away hatred from your hearts — in deed, in word, and in the inclination of the soul. He had spoken peaceably to Joseph before his father while the spirit of hatred darkened his mind; now he commands the love Torah commands. It ain''t new — love thy neighbour as thyself is Moses'' own word, and the message John says was heard from the beginning.',
       sv.verse_id, ev.verse_id, 'extras', 89475
  FROM _session413_t100_lookup sv, _session413_t100_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=100 AND sv.verse_number=1
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=100 AND ev.verse_number=3
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-100-if-he-repent-forgive-him',
       E'If a man sin against thee — rebuke, and if he repent, forgive him',
       E'Gad lays down the rule: if a man sin against thee, speak peaceably to him and hold no guile; if he repent and confess, forgive him. The Messiah gives word for word the same order — go and tell him his fault, and forgive thy brother seventy times seven. It ain''t new — the Lord''s forgiveness teaching and Gad''s deathbed counsel are one path of rebuke-and-pardon.',
       sv.verse_id, ev.verse_id, 'extras', 89478
  FROM _session413_t100_lookup sv, _session413_t100_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=100 AND sv.verse_number=3
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=100 AND ev.verse_number=6
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-100-forgive-from-the-heart-leave-to-god-the-avenging',
       E'Even the shameless — forgive him from the heart, and leave to God the avenging',
       E'Gad reaches the hardest word: even if a man be shameless and persist in his wrong-doing, even so forgive him from the heart, and leave to God the avenging. Paul says forgive even as God forgave you; the Lord says forgive from your hearts; and vengeance belongs to God alone. It ain''t new — heart-forgiveness that leaves vengeance to God is Moses, the Messiah, and the apostle in one voice.',
       sv.verse_id, ev.verse_id, 'extras', 89481
  FROM _session413_t100_lookup sv, _session413_t100_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=100 AND sv.verse_number=3
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=100 AND ev.verse_number=7
