CREATE TEMP VIEW _session413_t101_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-101-be-not-envious-of-the-prosperous
  ('pseudepigrapha', 'testaments-xii', 101, 1, 'canon', 'psalms', 37, 1, 'free', E'Psalms 37:1 — *Fret not thyself because of evildoers, neither be thou envious against the workers of iniquity.* Gad''s ''be not vexed... be not envious'' when another prospers is David''s own counsel against envy.'),
  ('pseudepigrapha', 'testaments-xii', 101, 7, 'canon', 'psalms', 37, 7, 'free', E'Psalms 37:7 — *Rest in Yahuah (LORD), and wait patiently for him: fret not thyself because of him who prospereth in his way...* To put away jealousy and rest in God is the patient waiting the psalm commands toward the prosperous.'),
  -- thread: testaments-xii-101-wealth-by-evil-means-wait-for-the-end-of-the-lord
  ('pseudepigrapha', 'testaments-xii', 101, 4, 'canon', 'psalms', 37, 35, 'free', E'Psalms 37:35 — *I have seen the wicked in great power, and spreading himself like a green bay tree.* The man grown rich by evil means whom Gad bids us not envy is the flourishing wicked the psalmist beholds.'),
  ('pseudepigrapha', 'testaments-xii', 101, 4, 'canon', 'psalms', 37, 36, 'free', E'Psalms 37:36 — *Yet he passed away, and, lo, he was not: yea, I sought him, but he could not be found.* To wait for the end of the Lord upon the unrepentant rich is the psalm''s very picture of the wicked passing away.')
)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM input i
  JOIN _session413_t101_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _session413_t101_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- ----- threads -----
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-101-be-not-envious-of-the-prosperous',
       E'If a man prosper more than you, be not vexed but pray for him',
       E'Gad turns from hatred to its twin, envy: if a man prospereth more than you, be not vexed but pray for him; if he be exalted, be not envious. David''s psalm gives the same medicine — fret not thyself because of evildoers, neither be envious against the workers of iniquity. It ain''t new — Gad''s cure for envy is the song Israel already sang.',
       sv.verse_id, ev.verse_id, 'extras', 89500
  FROM _session413_t101_lookup sv, _session413_t101_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=101 AND sv.verse_number=1
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=101 AND ev.verse_number=7
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-101-wealth-by-evil-means-wait-for-the-end-of-the-lord',
       E'Though a man grow rich by evil means as Esau — wait for the end of the Lord',
       E'Gad counsels that though a man become rich by evil means, even as Esau, be not jealous but wait for the end of the Lord — for the unrepentant is reserved for eternal punishment, while the poor man free from envy is blessed beyond all men. The psalm shows the same end: the wicked spreading like a green bay tree, yet passing away and found no more. It ain''t new — the testament''s patience is the psalmist''s confidence in how the wicked end.',
       sv.verse_id, ev.verse_id, 'extras', 89503
  FROM _session413_t101_lookup sv, _session413_t101_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=101 AND sv.verse_number=4
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=101 AND ev.verse_number=4
ON CONFLICT (slug) DO NOTHING;

