INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-104-hares-half-clean-the-commandments',
       E'The hare — half clean yet unclean, by the tables of the commandments',
       E'Asher''s catalogue of the two-faced man ends in a striking figure: the man who sins greatly yet keeps some commandments, who fasts yet does evil, is like the hare — half clean, but in very deed unclean — for, he says, God in the tables of the commandments hath thus declared. The patriarch reaches straight for Torah''s law of clean and unclean, where the hare is named unclean because it answers one mark of cleanness but not the other. It ain''t new — Asher reads the two-faced soul off the very dietary law Moses wrote, and treats those commandments as standing and binding.',
       sv.verse_id, ev.verse_id, 'extras', 89575
  FROM _session413_t104_lookup sv, _session413_t104_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=104 AND sv.verse_number=9
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=104 AND ev.verse_number=10
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-104-defraudeth-yet-pitieth-the-poor',
       E'He defraudeth his neighbour, yet pitieth the poor — the whole is evil',
       E'Among the two-faced men Asher exposes is the one who defrauds his neighbour, swears falsely, sets the law of the Lord at nought — and yet pities the poor, as though the one good covers the many evils. Torah forbids the very fraud and false swearing he indulges, and the Lord who commands the law is the One he provokes. It ain''t new — Asher measures the double-faced almsgiver by the law of the Lord that he sets at nought.',
       sv.verse_id, ev.verse_id, 'extras', 89578
  FROM _session413_t104_lookup sv, _session413_t104_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=104 AND sv.verse_number=6
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=104 AND ev.verse_number=8
ON CONFLICT (slug) DO NOTHING;

