INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-108-keep-the-law-with-singleness-of-face',
       E'Keep the law of the Lord — the double-faced sin twofold',
       E'Asher exhorts his children to keep the commandments and the law of the Lord, following truth with singleness of face, for the double-faced are guilty of a twofold sin — both doing evil and delighting in those who do it. The apostle marks the same double guilt of those who not only do such things but have pleasure in them that do them, and James calls the wavering, double-minded man unstable. It ain''t new — Asher''s charge to keep the law with one face is the apostolic call away from the twofold sin of the divided heart.',
       sv.verse_id, ev.verse_id, 'extras', 89675
  FROM _session413_t108_lookup sv, _session413_t108_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=108 AND sv.verse_number=2
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=108 AND ev.verse_number=3
