INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-108-the-soul-departing-angel-of-peace',
       E'The latter end of a man — the angel of peace and eternal life',
       E'Asher tells how the latter ends of men show their righteousness: the troubled soul departs to torment by the evil spirit it served, but the peaceful soul meets the angel of peace, who leads it into eternal life. The two ways run all the way to the two ends Moses set before Israel — life and death — and to the eternal life laid up for them that love the Lord. It ain''t new — the two destinies Asher sees at death are the life and death Deuteronomy set before every soul, and the crown of life the apostle promises.',
       sv.verse_id, ev.verse_id, 'extras', 89678
  FROM _session413_t108_lookup sv, _session413_t108_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=108 AND sv.verse_number=4
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=108 AND ev.verse_number=6
ON CONFLICT (slug) DO NOTHING;

