-- ----- fragment: minion_testamentsxii_111.sql (session413 testaments-xii 111) -----
-- Source anchor: pseudepigrapha/testaments-xii ch111. Targets span Tanakh + NT (canon) + extra-canonical.
-- Tag: t111 (view _session413_t111_lookup). Sort band base 89750, step 3. Idempotent ON CONFLICT.

CREATE TEMP VIEW _session413_t111_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-111-the-lord-was-with-joseph
  ('pseudepigrapha', 'testaments-xii', 111, 4, 'canon', 'psalms', 105, 17, 'free', E'Psalm 105:17 — *He sent a man before them, even Joseph, who was sold for a servant.* The Psalmist names the same selling Joseph here confesses, and reads it as God''s own sending.'),
  ('pseudepigrapha', 'testaments-xii', 111, 5, 'canon', 'psalms', 105, 18, 'free', E'Psalm 105:18 — *Whose feet they hurt with fetters: he was laid in iron.* Joseph''s "I was taken into captivity" and "in bonds" is the very binding the Psalm records.'),
  ('pseudepigrapha', 'testaments-xii', 111, 5, 'canon', 'psalms', 105, 19, 'free', E'Psalm 105:19 — *Until the time that his word came: the word of Yahuah (LORD) tried him.* The trying and deliverance Joseph recounts is exactly how the Psalmist frames his ordeal.'),
  ('pseudepigrapha', 'testaments-xii', 111, 4, 'canon', 'genesis', 39, 2, 'free', E'Genesis 39:2 — *And Yahuah (LORD) was with Joseph, and he was a prosperous man; and he was in the house of his master the Egyptian.* The refrain of the whole testament — "Yahuah loved me... the God of my fathers guarded me" — is Moses'' own refrain over Joseph.')
)
