-- Tag: t120 (view _session413_t120_lookup). Sort band base 89975, step 3. Idempotent ON CONFLICT.

CREATE TEMP VIEW _session413_t120_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-120-i-refrained-from-shaming-my-brethren
  ('pseudepigrapha', 'testaments-xii', 120, 6, 'canon', 'genesis', 50, 20, 'free', E'Genesis 50:20 — *But as for you, ye thought evil against me; but Elohim (God) meant it unto good, to bring to pass, as it is this day, to save much people alive.* That he would not raise himself against his brethren "with evil intent" is the same spirit that forgave them at the last.'),
  ('pseudepigrapha', 'testaments-xii', 120, 2, 'canon', '1-peter', 2, 23, 'free', E'1 Peter 2:23 — *Who, when he was reviled, reviled not again; when he suffered, he threatened not; but committed himself to him that judgeth righteously.* Joseph''s patience under slavery, slander and envy — committing his cause to Yahuah who dwells in the chaste — is the Messiah''s own pattern of suffering.')
)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM input i
  JOIN _session413_t120_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _session413_t120_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- ----- threads -----
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-120-i-refrained-from-shaming-my-brethren',
       E'Sold, he refrained from telling he was the son of Jacob',
       E'Joseph turns from the chastity narrative to its fruit: how great things patience and prayer with fasting work, so that the Most High dwells with the chaste and exalts him. He marks his own restraint — though loved above his brethren and being sold by them, he did not raise himself against them with evil intent, but out of respect refused to tell the Ishmaelites that he was the son of Jacob. It ain''t new — this is the Joseph who would say, ye thought evil, but God meant it unto good.',
       sv.verse_id, ev.verse_id, 'extras', 89975
  FROM _session413_t120_lookup sv, _session413_t120_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=120 AND sv.verse_number=2
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=120 AND ev.verse_number=6
ON CONFLICT (slug) DO NOTHING;

