  FROM cross_reference_threads t, cross_references x, _session413_t120_lookup sv, _session413_t120_lookup tv
 WHERE t.slug='testaments-xii-120-i-refrained-from-shaming-my-brethren'
   AND sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=120 AND sv.verse_number=6
   AND tv.edition_slug='canon' AND tv.book_slug='genesis' AND tv.chapter_number=50 AND tv.verse_number=20
   AND x.source_verse_id=sv.verse_id AND x.target_verse_id=tv.verse_id AND x.source='manual'
ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;

