INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-121-i-said-i-was-a-slave-to-spare-my-brethren',
       E'He confessed himself a slave that he might not put his brethren to shame',
       E'Joseph exhorts his sons to fear God and honour their brethren, for every one who does the law of Yahuah is loved by Him. He recalls that when the Ishmaelites asked whether he was a slave, he answered that he was a home-born slave, that he might not put his brethren to shame — choosing his own dishonour over their exposure. It ain''t new — to love thy neighbour as thyself, and to bear long with a brother''s fault, is the whole of the law.',
       sv.verse_id, ev.verse_id, 'extras', 90000
  FROM _session413_t121_lookup sv, _session413_t121_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=121 AND sv.verse_number=1
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=121 AND ev.verse_number=2
