INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-133-love-the-lord-and-thy-neighbour',
       E'Love the Lord God and keep His commandments, love thy neighbour',
       E'Benjamin''s whole charge stands on the two great commands: love the Lord God of heaven and earth and keep His commandments, and love thy neighbour. The man who does both — the example is Joseph — cannot be ruled by the spirit of Beliar, for he is shielded by the fear of God. It ain''t new — this is Moses and the Prophets in two clauses, the very pair the Messiah named the whole law and the prophets hang upon.',
       sv.verse_id, ev.verse_id, 'extras', 90300
  FROM _session413_t133_lookup sv, _session413_t133_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=133 AND sv.verse_number=1
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=133 AND ev.verse_number=5
