INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-133-joseph-prayed-for-his-brethren',
       E'Joseph besought his father to pray that their sin be not imputed',
       E'The mark of the good man, says Benjamin, is that Joseph asked Jacob to pray that the Lord would not impute to his brethren the evil they did him — the man who was sold interceding for those who sold him. Genesis sets the pattern: Joseph weeps, comforts, and forgives, naming the very providence that turned their evil to good. It ain''t new — the mercy that returns good for evil and prays for the offender is the Torah''s love-of-neighbour carried to its height.',
       sv.verse_id, ev.verse_id, 'extras', 90303
  FROM _session413_t133_lookup sv, _session413_t133_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=133 AND sv.verse_number=5
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=133 AND ev.verse_number=7
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-133-a-blameless-one-delivered-for-the-lawless',
       E'A blameless one delivered up for lawless men, for the salvation of all',
       E'Jacob''s blessing over Joseph reaches past Joseph: a prophecy that a blameless one shall be delivered up for lawless men, a sinless die for the ungodly, for the salvation of the Gentiles and of Israel, to destroy Beliar. The good man who was sold and forgave is the type; the Branch from Levi and Judah is the substance — the Anointed delivered up, raised, who brings salvation to the nations. It ain''t new — Isaiah''s lamb led to the slaughter is the root of which Joseph is the shadow.',
       sv.verse_id, ev.verse_id, 'extras', 90306
  FROM _session413_t133_lookup sv, _session413_t133_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=133 AND sv.verse_number=8
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=133 AND ev.verse_number=8
ON CONFLICT (slug) DO NOTHING;

