-- ----- fragment: minion_testamentsxii_134.sql (session413 testaments-xii 134) -----
-- Source anchor: pseudepigrapha/testaments-xii ch134. Targets span Tanakh + NT (canon) + extra-canonical.
-- Tag: t134 (view _session413_t134_lookup). Sort band base 90325, step 3. Idempotent ON CONFLICT.

CREATE TEMP VIEW _session413_t134_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-134-the-good-man-hath-no-dark-eye
  ('pseudepigrapha', 'testaments-xii', 134, 2, 'canon', 'matthew', 6, 22, 'free', E'Matt 6:22 — *The light of the body is the eye: if therefore thine eye be single, thy whole body shall be full of light.* — the single eye against the "dark eye" Benjamin names as the mark of the good man.'),
  ('pseudepigrapha', 'testaments-xii', 134, 2, 'canon', 'matthew', 5, 7, 'free', E'Matt 5:7 — *Blessed are the merciful: for they shall obtain mercy.* — the mercy to all, even to sinners, that the good man shows.'),
  ('pseudepigrapha', 'testaments-xii', 134, 4, 'canon', 'leviticus', 19, 18, 'free', E'Lev 19:18 — *thou shalt love thy neighbour as thyself: I am Yahuah (LORD).* — the love of the righteous "as his own soul" that crowns the good man''s mercy.'),
  -- thread: testaments-xii-134-by-doing-good-he-overcometh-evil
  ('pseudepigrapha', 'testaments-xii', 134, 3, 'canon', 'romans', 12, 21, 'free', E'Rom 12:21 — *Be not overcome of evil, but overcome evil with good.* — the very overcoming Benjamin names, "by doing good he overcometh evil."'),
  ('pseudepigrapha', 'testaments-xii', 134, 4, 'canon', 'romans', 12, 15, 'free', E'Rom 12:15 — *Rejoice with them that do rejoice, and weep with them that weep.* — the un-envying heart that praises the valiant and laughs not at another''s good.'),
  ('pseudepigrapha', 'testaments-xii', 134, 4, 'canon', 'proverbs', 14, 31, 'free', E'Prov 14:31 — *He that oppresseth the poor reproacheth his Maker: but he that honoureth him hath mercy on the poor.* — the mercy on the poor and compassion on the weak that marks the good man.')
)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM input i
  JOIN _session413_t134_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _session413_t134_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- ----- threads -----
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-134-the-good-man-hath-no-dark-eye',
       E'The good man hath not a dark eye, for he showeth mercy to all',
       E'The good man, Benjamin says, hath not a dark eye but shows mercy to all men, even sinners; on the poor he has mercy, on the weak compassion. The Messiah''s own teaching turns on the same image — the single eye that fills the whole body with light — and on the mercy that obtains mercy. It ain''t new — the bright eye and the merciful heart are the Torah''s love of neighbour seen plainly.',
       sv.verse_id, ev.verse_id, 'extras', 90325
  FROM _session413_t134_lookup sv, _session413_t134_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=134 AND sv.verse_number=1
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=134 AND ev.verse_number=4
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-134-by-doing-good-he-overcometh-evil',
       E'By doing good he overcometh evil, and envieth not',
       E'Though men devise evil against him, the good man overcomes evil by doing good, and he envies none — not the glorified, not the rich, not the valiant. Paul writes the same charge to the Romans almost word for word: be not overcome of evil, but overcome evil with good. It ain''t new — the apostle''s rule of the renewed mind is the deathbed wisdom of Benjamin.',
       sv.verse_id, ev.verse_id, 'extras', 90328
  FROM _session413_t134_lookup sv, _session413_t134_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=134 AND sv.verse_number=3
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=134 AND ev.verse_number=4
ON CONFLICT (slug) DO NOTHING;

