CREATE TEMP VIEW _session413_t139_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-139-the-words-of-enoch-fornication-of-sodom
  ('pseudepigrapha', 'testaments-xii', 139, 1, 'enoch', '1-enoch', 8, 2, 'free', E'1 Enoch 8:2 — *And there arose much godlessness, and they committed fornication, and they were led astray, and became corrupt in all their ways.* — the fornication Enoch foretold, which Benjamin draws from "the words of Enoch the righteous."'),
  ('pseudepigrapha', 'testaments-xii', 139, 1, 'enoch', '1-enoch', 9, 8, 'free', E'1 Enoch 9:8 — *And they have gone to the daughters of men upon the earth, and have slept with the women, and have defiled themselves, and revealed to them all kinds of sins.* — the wanton deeds with women Benjamin warns his sons they will renew.'),
  ('pseudepigrapha', 'testaments-xii', 139, 1, 'canon', 'jude', 1, 7, 'free', E'Jude 1:7 — *Even as Sodom and Gomorrha, and the cities about them in like manner, giving themselves over to fornication, and going after strange flesh, are set forth for an example.* — the fornication of Sodom set forth as warning, exactly as Benjamin invokes it.'),
  -- thread: testaments-xii-139-the-last-temple-the-tribes-and-the-gentiles-gathered
  ('pseudepigrapha', 'testaments-xii', 139, 2, 'canon', 'haggai', 2, 9, 'free', E'Hag 2:9 — *The glory of this latter house shall be greater than of the former, saith Yahuah Tseva''ot (LORD of hosts): and in this place will I give peace.* — the latter temple "more glorious than the first" Benjamin foresees.'),
  ('pseudepigrapha', 'testaments-xii', 139, 2, 'canon', 'isaiah', 2, 2, 'free', E'Isa 2:2 — *And it shall come to pass in the last days, that the mountain of the LORD''S house shall be established in the top of the mountains... and all nations shall flow unto it.* — the gathering of the tribes and all the Gentiles to the house of God.'),
  ('pseudepigrapha', 'testaments-xii', 139, 2, 'canon', 'ezekiel', 37, 22, 'free', E'Ezek 37:22 — *And I will make them one nation in the land... and they shall be no more two nations, neither shall they be divided into two kingdoms any more at all.* — the twelve tribes gathered together as one, the two-house reunion.'),
