INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-139-the-words-of-enoch-fornication-of-sodom',
       E'From the words of Enoch the righteous — the fornication of Sodom',
       E'Benjamin names his source: the words of Enoch the righteous, foreseeing that his sons will commit the fornication of Sodom and renew wanton deeds with women. Enoch''s own book records the fornication and the defiling with women that filled the earth with corruption, and Jude couples Sodom''s strange flesh with the angels who left their estate. It ain''t new — Benjamin reads the latter-day apostasy out of Enoch, the very witness the apostle Jude would later quote by name.',
       sv.verse_id, ev.verse_id, 'extras', 90450
  FROM _session413_t139_lookup sv, _session413_t139_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=139 AND sv.verse_number=1
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=139 AND ev.verse_number=1
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-139-the-last-temple-the-tribes-and-the-gentiles-gathered',
       E'The last temple more glorious, the twelve tribes and all Gentiles gathered',
       E'Yet the temple of God shall be in their portion, and the last temple more glorious than the first; there the twelve tribes shall be gathered, and all the Gentiles, until the Most High sends forth His salvation. Haggai promised the latter house greater than the former, and Isaiah saw all nations flowing to the mountain of the Lord''s house. It ain''t new — the two-house ingathering of all twelve tribes with the nations is the prophets'' settled hope.',
       sv.verse_id, ev.verse_id, 'extras', 90453
  FROM _session413_t139_lookup sv, _session413_t139_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=139 AND sv.verse_number=2
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=139 AND ev.verse_number=2
