INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-139-the-lord-lifted-up-upon-a-tree',
       E'The Lord lifted up upon a tree, and the veil of the temple rent',
       E'The prophecy then darkens: the Lord shall be treated with outrage and lifted up upon a tree, and the veil of the temple rent, and the Spirit pass to the Gentiles as fire poured forth. The Anointed of Levi and Judah is the one lifted up; Moses already wrote that the hanged one bears a curse, and the Gospel records the veil torn from top to bottom at the very hour. It ain''t new — the tree, the curse borne, and the rent veil are written in the Torah and fulfilled in the Branch.',
       sv.verse_id, ev.verse_id, 'extras', 90456
  FROM _session413_t139_lookup sv, _session413_t139_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=139 AND sv.verse_number=3
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=139 AND ev.verse_number=4
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-139-he-shall-ascend-from-hades-into-heaven',
       E'The Spirit to the Gentiles, and He shall ascend from Hades into heaven',
       E'The Spirit of God shall pass to the Gentiles as fire poured forth, and He shall ascend from Hades and pass from earth into heaven — lowly upon earth, glorious in heaven. Paul reads the same descent and ascent into the lower parts and up far above the heavens, and Peter tells how He preached to the spirits in prison. It ain''t new — the One who descends and ascends, pouring the Spirit on the nations, is the hope the prophets and apostles share.',
       sv.verse_id, ev.verse_id, 'extras', 90459
  FROM _session413_t139_lookup sv, _session413_t139_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=139 AND sv.verse_number=4
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=139 AND ev.verse_number=5
