CREATE TEMP VIEW _session413_t140_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-140-keep-the-commandments-till-he-reveal-salvation
  ('pseudepigrapha', 'testaments-xii', 140, 3, 'canon', 'deuteronomy', 30, 16, 'free', E'Deut 30:16 — *to love Yahuah Elohayka (the LORD thy God), to walk in his ways, and to keep his commandments and his statutes and his judgments, that thou mayest live.* — the very keeping Benjamin leaves "instead of inheritance."'),
  ('pseudepigrapha', 'testaments-xii', 140, 5, 'canon', 'isaiah', 49, 6, 'free', E'Isa 49:6 — *I will also give thee for a light to the Gentiles, that thou mayest be my salvation unto the end of the earth.* — the salvation revealed "to all Gentiles" that the fathers'' charge waits for.'),
  ('pseudepigrapha', 'testaments-xii', 140, 5, 'canon', 'acts', 13, 47, 'free', E'Acts 13:47 — *I have set thee to be a light of the Gentiles, that thou shouldest be for salvation unto the ends of the earth.* — the apostles'' citation of the same promise, salvation to the Gentiles.'),
  -- thread: testaments-xii-140-the-patriarchs-rise-each-over-his-tribe
  ('pseudepigrapha', 'testaments-xii', 140, 6, 'canon', 'matthew', 22, 32, 'free', E'Matt 22:32 — *I am the Elohim (God) of Abraham, and the Elohim (God) of Isaac, and the Elohim (God) of Jacob? Elohim (God) is not the Elohim (God) of the dead, but of the living.* — the fathers who live to God, who Benjamin sees "rising on the right hand in gladness."'),
  ('pseudepigrapha', 'testaments-xii', 140, 7, 'canon', 'matthew', 19, 28, 'free', E'Matt 19:28 — *ye also shall sit upon twelve thrones, judging the twelve tribes of Yashar''el (Israel).* — the twelve set "each one over our tribe," as Benjamin foresees.'),
  ('pseudepigrapha', 'testaments-xii', 140, 6, 'canon', 'ezekiel', 37, 12, 'free', E'Ezek 37:12 — *Behold, O my people, I will open your graves, and cause you to come up out of your graves.* — the raising of Israel and her fathers from the grave.'),
  -- thread: testaments-xii-140-all-men-shall-rise-some-to-glory-some-to-shame
  ('pseudepigrapha', 'testaments-xii', 140, 8, 'canon', 'daniel', 12, 2, 'free', E'Dan 12:2 — *And many of them that sleep in the dust of the earth shall awake, some to everlasting life, and some to shame and everlasting contempt.* — the very words behind "all men shall rise, some unto glory and some unto shame."'),
  ('pseudepigrapha', 'testaments-xii', 140, 8, 'canon', 'john', 5, 29, 'free', E'John 5:29 — *And shall come forth; they that have done good, unto the resurrection of life; and they that have done evil, unto the resurrection of damnation.* — the two resurrections, to glory and to shame.'),
  ('pseudepigrapha', 'testaments-xii', 140, 8, 'canon', 'revelation', 20, 12, 'free', E'Rev 20:12 — *And I saw the dead, small and great, stand before Elohim (God)... and the dead were judged out of those things which were written in the books, according to their works.* — all men risen and judged, as Benjamin foresees.'),
  -- thread: testaments-xii-140-israel-convicted-through-the-chosen-gentiles
  ('pseudepigrapha', 'testaments-xii', 140, 10, 'canon', 'romans', 11, 11, 'free', E'Rom 11:11 — *through their fall salvation is come unto the Gentiles, for to provoke them to jealousy.* — Israel convicted and provoked through the believing Gentiles, exactly as Benjamin foresees.'),
  ('pseudepigrapha', 'testaments-xii', 140, 9, 'canon', 'acts', 13, 46, 'free', E'Acts 13:46 — *It was necessary that the word of Elohim (God) should first have been spoken to you: but seeing ye put it from you... lo, we turn to the Gentiles.* — judgment of Israel first, then the turning to the Gentiles.'),
  ('pseudepigrapha', 'testaments-xii', 140, 10, 'canon', 'romans', 11, 25, 'free', E'Rom 11:25 — *blindness in part is happened to Yashar''el (Israel), until the fulness of the Gentiles be come in.* — the chosen Gentiles brought in to convict and gather Israel.')
)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM input i
  JOIN _session413_t140_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _session413_t140_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- ----- threads -----
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-140-keep-the-commandments-till-he-reveal-salvation',
       E'Keep the law and commandments, the fathers'' inheritance, till salvation comes',
       E'Benjamin''s dying charge is the fathers'' charge: keep the law of the Lord and His commandments, the inheritance Abraham, Isaac, and Jacob handed down — until the Lord reveal His salvation to all Gentiles. Moses set the same commandment as Israel''s very life, and Isaiah promised the Servant given for a light to the Gentiles. It ain''t new — the keeping of the commandments and the salvation reaching the nations are one inheritance from the fathers.',
       sv.verse_id, ev.verse_id, 'extras', 90475
  FROM _session413_t140_lookup sv, _session413_t140_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=140 AND sv.verse_number=3
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=140 AND ev.verse_number=5
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-140-the-patriarchs-rise-each-over-his-tribe',
       E'Enoch, Noah, and the fathers rise — each one over his tribe',
       E'Then, Benjamin says, you shall see Enoch, Noah, Shem, Abraham, Isaac, and Jacob rising on the right hand in gladness, and we also rise, each one over his tribe, worshipping the King of heaven. The Messiah declared God the God of the living, not the dead — the fathers live to Him — and promised the twelve to sit on thrones judging the twelve tribes. It ain''t new — the rising of the fathers and the twelve set over the tribes is the resurrection hope the Gospel confirms.',
       sv.verse_id, ev.verse_id, 'extras', 90478
  FROM _session413_t140_lookup sv, _session413_t140_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=140 AND sv.verse_number=6
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=140 AND ev.verse_number=7
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-140-all-men-shall-rise-some-to-glory-some-to-shame',
       E'All men shall rise, some unto glory and some unto shame',
       E'The resurrection is universal: all men shall rise, some unto glory and some unto shame, and the Lord shall judge Israel first for their unrighteousness. Daniel saw the sleepers awake, some to everlasting life and some to shame; the Messiah named the resurrection of life and the resurrection of damnation; John saw the dead, small and great, judged out of the books. It ain''t new — the twofold rising to glory or shame is Daniel''s own vision, sealed in the prophets and the apostles.',
       sv.verse_id, ev.verse_id, 'extras', 90481
  FROM _session413_t140_lookup sv, _session413_t140_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=140 AND sv.verse_number=8
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=140 AND ev.verse_number=8
ON CONFLICT (slug) DO NOTHING;

INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'testaments-xii-140-israel-convicted-through-the-chosen-gentiles',
       E'He shall convict Israel through the chosen ones of the Gentiles',
       E'Then He shall judge the Gentiles, and convict Israel through the chosen ones of the Gentiles — those who believed entering into the portion of them that fear the Lord. Paul writes the same mystery: through Israel''s fall salvation came to the Gentiles, to provoke them to jealousy, that Israel might be saved. It ain''t new — that the believing nations would stir Israel to her own salvation is the apostle''s mystery, foreseen here on Benjamin''s deathbed.',
       sv.verse_id, ev.verse_id, 'extras', 90484
  FROM _session413_t140_lookup sv, _session413_t140_lookup ev
 WHERE sv.edition_slug='pseudepigrapha' AND sv.book_slug='testaments-xii' AND sv.chapter_number=140 AND sv.verse_number=9
   AND ev.edition_slug='pseudepigrapha' AND ev.book_slug='testaments-xii' AND ev.chapter_number=140 AND ev.verse_number=10
ON CONFLICT (slug) DO NOTHING;

