-- ----- fragment: minion_testamentsxii_141.sql (session413 testaments-xii 141) -----
-- Source anchor: pseudepigrapha/testaments-xii ch141. Targets span Tanakh + NT (canon) + extra-canonical.
-- Tag: t141 (view _session413_t141_lookup). Sort band base 90500, step 3. Idempotent ON CONFLICT.

CREATE TEMP VIEW _session413_t141_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-141-all-israel-gathered-and-the-wolf-no-more
  ('pseudepigrapha', 'testaments-xii', 141, 1, 'canon', 'genesis', 49, 27, 'free', E'Gen 49:27 — *Benjamin shall ravin as a wolf: in the morning he shall devour the prey, and at night he shall divide the spoil.* — the very wolf Benjamin says he shall "no longer be called."'),
  ('pseudepigrapha', 'testaments-xii', 141, 1, 'canon', 'deuteronomy', 30, 4, 'free', E'Deut 30:4 — *from thence will Yahuah Elohayka (the LORD thy God) gather thee, and from thence will he fetch thee.* — the gathering of "all Israel unto the Lord" Benjamin foresees.'),
  ('pseudepigrapha', 'testaments-xii', 141, 1, 'canon', 'ezekiel', 37, 21, 'free', E'Ezek 37:21 — *Behold, I will take the children of Yashar''el (Israel) from among the heathen... and will gather them on every side, and bring them into their own land.* — the ingathering that makes the dispersed dwell securely again.'),
  -- thread: testaments-xii-141-one-beloved-of-the-lord-of-benjamins-seed
  ('pseudepigrapha', 'testaments-xii', 141, 2, 'canon', 'deuteronomy', 33, 12, 'free', E'Deut 33:12 — *The beloved of Yahuah (LORD) shall dwell in safety by him; and Yahuah (LORD) shall cover him all the day long.* — the "one beloved of Yahuah" of Benjamin''s tribe, Moses'' own blessing on Benjamin.'),
  ('pseudepigrapha', 'testaments-xii', 141, 2, 'canon', 'philippians', 3, 5, 'free', E'Phil 3:5 — *of the stock of Yashar''el (Israel), of the tribe of Benjamin, an Hebrew of the Hebrews.* — Paul, the man of Benjamin''s seed, the beloved who enlightened the Gentiles.'),
  ('pseudepigrapha', 'testaments-xii', 141, 2, 'canon', 'romans', 11, 1, 'free', E'Rom 11:1 — *For I also am an Israelite, of the seed of Abraham, of the tribe of Benjamin.* — the apostle naming his own tribe, the beloved arisen in the latter days.'),
  ('pseudepigrapha', 'testaments-xii', 141, 3, 'canon', 'acts', 13, 47, 'free', E'Acts 13:47 — *I have set thee to be a light of the Gentiles.* — the beloved "enlightening the Gentiles" in their synagogues, as Benjamin foresees.')
)
