-- ----- fragment: minion_testamentsxii_142.sql (session413 testaments-xii 142) -----
-- Source anchor: pseudepigrapha/testaments-xii ch142. Targets span Tanakh + NT (canon) + extra-canonical.
-- Tag: t142 (view _session413_t142_lookup). Sort band base 90525, step 3. Idempotent ON CONFLICT.

CREATE TEMP VIEW _session413_t142_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29','josephus','lightfoot-apostolic-fathers','mrjames-apocryphal-nt');

WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, tier, note) AS (VALUES
  -- thread: testaments-xii-142-carry-up-my-bones-to-hebron
  ('pseudepigrapha', 'testaments-xii', 142, 1, 'canon', 'genesis', 50, 25, 'free', E'Gen 50:25 — *And Joseph took an oath of the children of Yashar''el (Israel), saying, Elohim (God) will surely visit you, and ye shall carry up my bones from hence.* — the same oath Benjamin lays on his sons, "carry up my bones out of Egypt."'),
  ('pseudepigrapha', 'testaments-xii', 142, 3, 'canon', 'exodus', 13, 19, 'free', E'Exod 13:19 — *And Moses took the bones of Joseph with him.* — the keeping of the fathers'' oath, the bones carried up out of Egypt as Benjamin commands.'),
  ('pseudepigrapha', 'testaments-xii', 142, 3, 'canon', 'joshua', 24, 32, 'free', E'Josh 24:32 — *And the bones of Joseph, which the children of Yashar''el (Israel) brought up out of Egypt, buried they in Shechem.* — the fathers'' bones at last brought into the land, the oath fulfilled.')
)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM input i
  JOIN _session413_t142_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _session413_t142_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

